package com.xdownload.mobile;
import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import android.content.*;import android.webkit.*;import android.net.Uri;
/** Local subresource filtering; no proxy, VPN, TLS interception, or remote browsing history. */
final class XShield {
 static final String SOURCE="https://adguardteam.github.io/AdGuardSDNSFilter/Filters/filter.txt";
 static final String[] BUILTIN=("doubleclick.net googlesyndication.com googleadservices.com google-analytics.com adservice.google.com googletagservices.com adnxs.com scorecardresearch.com taboola.com outbrain.com criteo.com criteo.net adsrvr.org pubmatic.com rubiconproject.com openx.net smartadserver.com advertising.com adform.net amazon-adsystem.com media.net serving-sys.com yieldmo.com indexww.com quantserve.com demdex.net bluekai.com rlcdn.com casalemedia.com sharethrough.com adsafeprotected.com doubleverify.com moatads.com gumgum.com bidswitch.net 2mdn.net googletagmanager.com app-measurement.com pixel.wp.com analytics.twitter.com bat.bing.com ads.linkedin.com adroll.com branch.io adjust.com appflyer.com appsflyer.com unityads.unity3d.com applovin.com inmobi.com chartboost.com vungle.com ironsrc.com supersonicads.com mopub.com adcolony.com propellerads.com popads.net popcash.net exoclick.com trafficjunky.net hilltopads.net adsterra.com clickadu.com ad-maven.com monetag.com pushground.com richpush.com revcontent.com mgid.com zergnet.com advertising.yahoo.com ads.yahoo.com adtech.de").split(" ");
 static String host(String raw){if(raw==null)return "";String h=raw.toLowerCase(Locale.ROOT);while(h.endsWith("."))h=h.substring(0,h.length()-1);return h.length()<=253&&h.matches("[a-z0-9-]+(?:\\.[a-z0-9-]+)+")?h:"";}
 static boolean suffix(Set<String> rules,String h){for(String k=h;!k.isEmpty();){if(rules.contains(k))return true;int i=k.indexOf('.');if(i<0)break;k=k.substring(i+1);}return false;}
 static final Set<String> BASE=Collections.unmodifiableSet(new HashSet<>(Arrays.asList(BUILTIN)));
 static final class Rules {
  final Set<String> block,allow;Rules(Set<String> b,Set<String> a){block=Collections.unmodifiableSet(b);allow=Collections.unmodifiableSet(a);}
  boolean blocks(String value){String h=host(value);return !h.isEmpty()&&!suffix(allow,h)&&(suffix(block,h)||suffix(BASE,h));}
  int count(){return block.size();}
 }
 static final Rules DEFAULT=new Rules(Collections.emptySet(),Collections.emptySet());
 static Rules parseDevice(Reader reader,int cap)throws IOException{HashSet<String>b=new HashSet<>(),a=new HashSet<>();int limit=Math.max(0,cap-cap/4);try(BufferedReader in=new BufferedReader(reader)){String line;while((line=in.readLine())!=null){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");if(line.length()>512)continue;line=line.trim();boolean exception=line.startsWith("@@||");String value=exception?line.substring(4):line.startsWith("||")?line.substring(2):"";if(!value.endsWith("^"))continue;String h=host(value.substring(0,value.length()-1));if(h.isEmpty()||h.equals("localhost"))continue;if(exception){a.add(h);if(a.size()>cap-limit)throw new IOException("Too many exceptions for device budget");}else if(b.size()<limit)b.add(h);}}return new Rules(b,a);}
 static void migrate(SharedPreferences p){if(p.getInt("shield_revision",0)<2)p.edit().putInt("shield_revision",2).putBoolean("block_trackers",true).apply();}
 static boolean adPath(Uri uri){String path=uri.getPath();if(path==null)return false;String x=path.toLowerCase(Locale.ROOT);if(x.length()>2048)return false;return x.matches(".*(?:/ads/|/adserver/|/ad-serving/|/adservice/|/adverts/|/advertising/).*")||x.matches(".*(?:/|^)(?:ad-banner|adserver|adsbygoogle|advertisement|adscript|banner-ad)(?:[-_.][a-z0-9_-]+)*\\.(?:js|gif|png|webp|jpg|html)$");}
 static boolean resourceBlocked(Rules r,Uri uri,String top){String h=host(uri.getHost());if(h.isEmpty())return false;if(suffix(r.allow,h))return false;return block(r,h,top,false,false)||adPath(uri);}
 static boolean navigationBlocked(Rules r,Uri uri,String top,boolean main,boolean gesture){if(main&&gesture)return false;return resourceBlocked(r,uri,top);}
 static boolean shouldAutoUpdate(SharedPreferences p,long now){return p.getBoolean("shield_auto",true)&&p.getBoolean("block_trackers",true)&&now-p.getLong("shield_attempt",0)>24L*60*60*1000L&&(rules.count()==0||now-p.getLong("shield_success",0)>7L*24*60*60*1000L);}

 static volatile Rules rules=DEFAULT;
 static Rules parse(Reader reader,int cap)throws IOException{HashSet<String>b=new HashSet<>(),a=new HashSet<>();try(BufferedReader in=new BufferedReader(reader)){String line;while((line=in.readLine())!=null){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");if(line.length()>512)continue;line=line.trim();boolean exception=line.startsWith("@@||");String value=exception?line.substring(4):line.startsWith("||")?line.substring(2):"";if(!value.endsWith("^"))continue;String h=host(value.substring(0,value.length()-1));if(h.isEmpty()||h.equals("localhost"))continue;(exception?a:b).add(h);if(b.size()+a.size()>cap)throw new IOException("Filter exceeds this device memory budget");}}return new Rules(b,a);}
 static int cap(){long heap=Runtime.getRuntime().maxMemory();return (int)Math.min(85000,Math.max(5000,heap/1024/2));}
 static File file(Context c){return new File(c.getNoBackupFilesDir(),"xshield-filter.txt");}
 static synchronized void load(Context c){File f=file(c);if(!f.isFile()||f.length()>8L*1024*1024)return;try(Reader r=new InputStreamReader(new FileInputStream(f),java.nio.charset.StandardCharsets.UTF_8)){Rules next=parseDevice(r,cap());if(next.count()>=1000)rules=next;}catch(Exception ignored){}}
 static synchronized int update(Context c)throws Exception{File target=file(c),tmp=File.createTempFile("xshield-",".tmp",target.getParentFile());java.net.HttpURLConnection con=HttpEngine.connect(SOURCE,false,"GET",0,"");try{if(con.getResponseCode()!=200)throw new IOException("Filter server unavailable");try(InputStream in=con.getInputStream();FileOutputStream out=new FileOutputStream(tmp)){byte[] buf=new byte[32768];int n;long total=0;while((n=in.read(buf))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Cancelled");total+=n;if(total>8L*1024*1024)throw new IOException("Filter too large");out.write(buf,0,n);}out.getFD().sync();}Rules next;try(Reader r=new InputStreamReader(new FileInputStream(tmp),java.nio.charset.StandardCharsets.UTF_8)){next=parseDevice(r,cap());}if(next.count()<1000)throw new IOException("Incomplete filter");java.nio.file.Files.move(tmp.toPath(),target.toPath(),java.nio.file.StandardCopyOption.ATOMIC_MOVE,java.nio.file.StandardCopyOption.REPLACE_EXISTING);rules=next;return next.count();}finally{con.disconnect();tmp.delete();}}
 static boolean enabled(SharedPreferences p,String top){return p.getBoolean("block_trackers",true)&&!p.getBoolean("shield_allow_"+host(top),false);}
 static boolean block(Rules r,String requested,String top,boolean main,boolean gesture){String h=host(requested),t=host(top);if(h.isEmpty()||h.equals(t)||!t.isEmpty()&&h.endsWith("."+t))return false;if(main&&gesture)return false;return r.blocks(h);}
 static WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",204,"No Content",Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}
 static final class Session{volatile String top="";final AtomicInteger blocked=new AtomicInteger(),redirects=new AtomicInteger();void start(String url){String h=host(Uri.parse(url).getHost());if(!h.equals(top)){top=h;blocked.set(0);redirects.set(0);}}}
 static final String COSMETIC="(function(){if(document.getElementById('xshield-css'))return;let s=document.createElement('style');s.id='xshield-css';s.textContent='ins.adsbygoogle,iframe[src*=\"doubleclick.net\"],iframe[src*=\"googlesyndication.com\"],[data-ad-slot],[data-ad-client],[data-google-query-id],.ad-banner,.advertisement,.adsbygoogle,#ad-banner,#advertisement{display:none!important}';(document.head||document.documentElement).appendChild(s)})()";
}
